="140"><template #default="{row}">{{ actionLabels[row.meta.operation] || row.meta.operation }} · {{ row.meta.success ? '成功' : '失败' }}</template></el-table-column><el-table-column prop="userId" label="实际操作人" min-width="150"/><el-table-column label="结果" min-width="120"><template #default="{row}">{{ row.meta.code || (row.meta.success ? '完成' : '失败') }}</template></el-table-column><el-table-column label="时间（北京时间）" min-width="170"><template #default="{row}">{{ time(row.createdAt) }}</template></el-table-column></el-table><p>展示最近30条平台管理结果；不记录正文或token。</p></el-tab-pane></el-tabs></div><template #footer><el-button @click="detailOpen = false">关闭</el-button></template></el-dialog>
