async function loadTenants(){const seq=++listSequence;loading.value=true;try{const result=await adminLibraryTenants({q:tenantSearch.value,page:tenantPage.value,pageSize:tenantPageSize.value});if(!alive||seq!==listSequence)return;tenants.value=result.items;tenantTotal.value=result.total;error.value='';}catch(e){if(alive&&seq===listSequence){tenants.value=[];error.value=message(e);}}finally{if(alive&&seq===listSequence)loading.value=false;}}
