async function uploadOne(file:File,progress:(ratio:number)=>void,folderPath:readonly string[]=[]){if(!uploadPlan)throw new Error('请先确认上传目标');let requestId=uploadIds.get(file);if(!requestId){requestId=crypto.randomUUID();uploadIds.set(file,requestId);}let body:AdminTarget|Omit<AdminCommand,'requestId'>=uploadPlan.body;if(!uploadPlan.replace&&folderPath.length){const target=uploadPlan.body as AdminTarget;let parentId=target.parentId;for(let index=0;index<folderPath.length;index+=1){const name=folderPath[index]!;const key=`${parentId||'root'}\u0000${folderPath.slice(0,index+1).join('/')}`;let next=uploadFolderCache.get(key);if(!next){const created=await adminLibraryFolder(uploadPlan.tenant,{name,parentId,ownerUserId:target.ownerUserId,scope:target.scope,confirmShare:target.confirmShare,reuseExisting:true,requestId:crypto.randomUUID()});next=created.nodeId;uploadFolderCache.set(key,next);}parentId=next;}body={...target,parentId};}await adminLibraryUpload(uploadPlan.tenant,{...body,requestId},file,progress,uploadPlan.replace);return '已保存；AI可用性以处理状态为准';}
