async function purgeItem(item:AdminItem){if(!item.canWrite||busy.value||item.purgeBlockedReason)return;try{await confirmDelete({name:item.name,description:'彻底删除该资料及其中的全部内容与版本；旧引用会显示来源不可用，不会改指向其它版本。',title:'彻底删除资料？',confirmText:'彻底删除',customClass:'library-message-box'});busy.value=true;await adminLibraryCommand(tenantId.value,{...commandBase(item,'purge'),confirmPurge:true,requestId:crypto.randomUUID()});ElMessage.success('已彻底删除');await reload();}catch(e){if(e!=='cancel')error.value=message(e);}finally{busy.value=false;}}
async function restoreItem(item:AdminItem){if(!item.canWrite||busy.value)return;try{busy.value=true;const body={...commandBase(item,'restore'),requestId:crypto.randomUUID()};try{await adminLibraryCommand(tenantId.value,body);}catch(e){if(e instanceof Error&&e.message.includes('原目录已不存在')){await ElMessageBox.confirm('原目录已不存在，将恢复到当前企业根目录。','恢复到根目录？',{customClass:'library-message-box',confirmButtonText:'恢复',cancelButtonText:'取消'});await adminLibraryCommand(tenantId.value,{...body,confirmMissingParent:true,requestId:crypto.randomUUID()});}else throw e;}ElMessage.success('已恢复');await reload();}catch(e){if(e!=='cancel')error.value=message(e);}finally{busy.value=false;}}
async function confirmScope(item:AdminItem){if(!item.canWrite||item.state!=='ACTIVE'||busy.value)return;const target=item.scope==='PRIVATE'?'ENTERPRISE':'PRIVATE';try{const impact=await adminLibraryScopeImpact(tenantId.value,item,target);const count=Math.max(0,impact.total-(item.kind==='FOLDER'?1:0));const text=target==='ENTERPRISE'?`当前位置的全部内容会一起共享，本企业成员可见，共涉及 ${count} 项。`:`当前位置的全部内容会改为各自所有者私有，共涉及 ${count} 项。`;try{await ElMessageBox.confirm(text,target==='ENTERPRISE'?'确认共享':'确认取消共享',{customClass:'library-message-box',confirmButtonText:'确定',cancelButtonText:'取消'});}catch{return;}busy.value=true;await adminLibraryCommand(tenantId.value,{nodeId:item.id,action:'scope',expectedUpdatedAt:item.updatedAt,...(item.currentVersion?{expectedVersionId:item.currentVersion.id}:{}),scope:target,confirmShare:target==='ENTERPRISE',confirmUnshare:target==='PRIVATE',expectedTreeRevision:impact.treeRevision,requestId:crypto.randomUUID()});ElMessage.success(target==='ENTERPRISE'?'已共享到企业':'已撤销共享');await reload();}catch(e){error.value=message(e);}finally{busy.value=false;}}
function openRecycleBin(){query.state='RECYCLED';query.scope='';search();}
function noticeRecycled(){ElMessage({type:'success',duration:6000,showClose:true,message:h('span',['已移入回收站。',h('button',{type:'button',class:'el-button el-button--primary is-link',onClick:()=>openRecycleBin()},'打开回收站')])});}
async function saveOperation(){if(busy.value||!operationRow.value||operation.value==='impact')return;const item=operationRow.value,id=tenantId.value,current=epoch;try{const body:AdminCommand={...commandBase(item,operation.value),requestId:crypto.randomUUID()};if(operation.value==='rename')body.name=operationName.value;if(operation.value==='move'){const parentId=movePath.value.at(-1)?.id||undefined;body.parentId=parentId;const destination=parentId?options.value?.folders.find(folder=>folder.id===parentId):undefined;if(destination?.scope==='ENTERPRISE'){const impact=await adminLibraryScopeImpact(id,item,'ENTERPRISE');if(impact.changed){try{await ElMessageBox.confirm(`移入共享目录会共享当前位置的全部内容，共涉及 ${Math.max(0,impact.total-(item.kind==='FOLDER'?1:0))} 项。`,'确认移动并共享',{customClass:'library-message-box'});}catch{return;}}body.confirmShare=true;body.expectedTreeRevision=impact.treeRevision;}}if(operation.value==='scope'){body.scope=item.scope==='PRIVATE'?'ENTERPRISE':'PRIVATE';if(!scopeImpact.value)throw new Error('请等待影响范围加载完成');body.confirmShare=body.scope==='ENTERPRISE';body.confirmUnshare=body.scope==='PRIVATE';body.expectedTreeRevision=scopeImpact.value.treeRevision;}if(operation.value==='purge'){if(!confirmPurge.value||!impact.value?.canPurge)throw new Error(impact.value?.blockedReason||'请核实删除影响并确认');body.confirmPurge=true;}if(operation.value==='restore')body.confirmMissingParent=confirmMissingParent.value;if(current!==epoch||!alive)return;busy.value=true;await adminLibraryCommand(id,body);if(current!==epoch||!alive)return;operationOpen.value=false;preview.value=undefined;if(body.action==='recycle')noticeRecycled();else ElMessage.success(`${actionLabels[body.action]}成功`);await reload();}catch(e){if(current===epoch)dialogError.value=message(e);}finally{if(current===epoch)busy.value=false;}}
const detailOpen=ref(false),detailRow=ref<AdminItem>(),detail=ref<AdminDetail>(),detailTab=ref('info'),detailError=ref(''),detailLoading=ref(false);
async function openDetail(item:AdminItem){const id=tenantId.value,seq=++detailSequence;detailRow.value=structuredClone(toRaw(item));detail.value=undefined;detailError.value='';detailTab.value='info';detailOpen.value=true;detailLoading.value=true;try{const value=await adminLibraryDetail(id,item.id);if(alive&&seq===detailSequence&&id===tenantId.value)detail.value=value;}catch(e){if(seq===detailSequence)detailError.value=message(e);}finally{if(seq===detailSequence)detailLoading.value=false;}}
const previewOpen=ref(false),preview=ref<LibraryPreview>(),previewRow=ref<AdminItem>(),previewMedia=ref(''),previewError=ref(''),previewLoading=ref(false);
const pdfUrl=ref(''),pdfLoading=ref(false),pdfError=ref('');
const previewIsPdf=computed(()=>preview.value?libraryPreviewIsPdf(preview.value):false);
function clearPdf(){if(pdfUrl.value)URL.revokeObjectURL(pdfUrl.value);pdfUrl.value='';}
watch(previewOpen,open=>{if(!open){previewSequence++;pdfLoading.value=false;pdfError.value='';clearPdf();}});
onBeforeUnmount(()=>{previewSequence++;clearPdf();});
async function previewItem(item:AdminItem,version?:string){
 if(!item.canRead)return;
 const id=tenantId.value,seq=++previewSequence;
 clearPdf();pdfError.value='';pdfLoading.value=false;preview.value=undefined;previewError.value='';previewMedia.value='';
 previewRow.value=structuredClone(toRaw(item));previewOpen.value=true;previewLoading.value=true;
 try{
  const value=await adminLibraryPreview(id,item,version);
  if(!alive||seq!==previewSequence||id!==tenantId.value)return;
  preview.value=value;
  if(value.previewKind==='image'||value.previewKind==='video'){previewMedia.value=value.versionId?adminLibraryDownload(id,item,value.versionId,true):'';return;}
  if(!libraryPreviewIsPdf(value)||!value.versionId)return;
  pdfLoading.value=true;
  const response=await fetch(adminLibraryDownload(id,item,value.versionId),{credentials:'include'});
  if(!response.ok)throw new Error('无法打开 PDF 原文件');
  const bytes=await response.arrayBuffer();
  if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw new Error('无法打开 PDF 原文件');
  if(seq!==previewSequence)return;
  pdfUrl.value=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
 }catch(e){
  if(seq!==previewSequence)return;
  if(preview.value&&libraryPreviewIsPdf(preview.value))pdfError.value=e instanceof Error?e.message:'无法打开 PDF 原文件';
  else previewError.value=message(e);
 }finally{if(seq===previewSequence){previewLoading.value=false;pdfLoading.value=false;}}
}
function download(item:AdminItem,version?:string){if(item.canRead)window.open(adminLibraryDownload(tenantId.value,item,version),'_blank','noopener');}
void reload();
</script>
